WITH chicago AS (
  SELECT `city_code` FROM `workspace`.`address_1`.`city` WHERE `city_name` ILIKE '%Chicago%'
), closest_city AS (
  SELECT dd.`city2_code`, dd.`distance`, c.`city_name`, RANK() OVER (ORDER BY dd.`distance` ASC) as rnk
  FROM `workspace`.`address_1`.`direct_distance` dd
  JOIN chicago ON dd.`city1_code` = chicago.`city_code`
  JOIN `workspace`.`address_1`.`city` c ON dd.`city2_code` = c.`city_code`
  WHERE dd.`city2_code` != chicago.`city_code`
)
SELECT `city_name` FROM closest_city WHERE rnk = 1;
